<div class="row g-3"><div class="col-xl-5"><div class="card"><div class="card-header border-bottom border-dashed"><h4 class="header-title mb-0">Cari Siswa</h4></div><div class="card-body"><div class="row g-2 align-items-end"><div class="col-md-10"><input id="q" class="form-control" placeholder="Nama/NIS/NISN"></div><div class="col-md-2 d-grid"><button class="btn btn-primary" onclick="cari()"><i class="ri-search-line me-1"></i>Cari</button></div></div><div id="hasil" class="mt-3"></div></div></div></div><div class="col-xl-7"><div class="card"><div class="card-header border-bottom border-dashed"><h4 class="header-title mb-0">Perubahan Status Siswa</h4></div><div class="card-body"><form id="form"><input type="hidden" name="id_siswa"><div class="alert alert-info" id="identitas">Pilih siswa terlebih dahulu.</div><div class="row g-3"><div class="col-md-6"><label class="form-label">Status Baru</label><select name="status_baru" class="form-select"><option>Pindah Sekolah</option><option>Berhenti</option></select></div><div class="col-md-6"><label class="form-label">Tanggal</label><input name="tanggal" class="form-control tanggal" value="<?= date('d-m-Y') ?>"></div><div class="col-12"><label class="form-label">Alasan</label><textarea name="alasan" class="form-control" required></textarea></div><div class="col-12"><button type="button" id="btn_proses" class="btn btn-primary">Simpan Perubahan Status</button></div></div></form></div></div></div></div>
<script>
$(function(){flatpickr('.tanggal',{dateFormat:'d-m-Y'});$('#q').keyup(function(e){if(e.key==='Enter')cari();});$('#btn_proses').click(proses);});
function cari(){$.post('<?= base_url('status_siswa/cari') ?>',{q:$('#q').val()},function(rows){var h='';if(!rows.length)h='<div class="empty-state">Siswa tidak ditemukan.</div>';rows.forEach(function(r){h+='<button type="button" class="list-group-item list-group-item-action border rounded mb-2" onclick=\'pilih('+JSON.stringify(r)+')\'><strong>'+escapeHtml(r.nama_lengkap)+'</strong><br><small>'+escapeHtml(r.nis)+' | '+escapeHtml(r.nama_kelas||'Belum ditempatkan')+' | '+escapeHtml(r.status_pendaftaran)+'</small></button>';});$('#hasil').html(h);},'json').fail(ajaxError);}
function pilih(r){$('#form [name=id_siswa]').val(r.id);$('#identitas').html('<strong>'+escapeHtml(r.nama_lengkap)+'</strong><br>NIS '+escapeHtml(r.nis)+' | Kelas: '+escapeHtml(r.nama_kelas||'-')+' | Status: '+escapeHtml(r.status_pendaftaran));}
function proses(){if(!$('#form [name=id_siswa]').val())return Swal.fire('Perhatian','Pilih siswa terlebih dahulu.','warning');confirmAction('Simpan perubahan status?','Siswa tidak ikut tagihan baru, tetapi tagihan lama tetap tersimpan.',function(){$.post('<?= base_url('status_siswa/proses') ?>',$('#form').serialize(),function(r){Swal.fire(r.result==='true'?'Berhasil':'Gagal',r.message,r.result==='true'?'success':'error');if(r.result==='true')location.reload();},'json').fail(ajaxError);});}
</script>
